import{z as n,x as B,o as t,c as d,q as r,j as l,D as e,d as E,s,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"git 的内部模型","description":"","frontmatter":{"title":"git 的内部模型","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-git-internals.md","filePath":"cs/swe-git-internals.md","lastUpdated":1791413859000}'),c={name:"cs/swe-git-internals.md"};function m(p,a,C,b,D,g){const o=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="git-的内部模型" tabindex="-1">git 的内部模型 <a class="header-anchor" href="#git-的内部模型" aria-label="Permalink to &quot;git 的内部模型&quot;">​</a></h1><div class="epigraph"><p>把内容按哈希入库，把名字做成指针：版本控制的全部机制都从这两个决定里长出来。</p><footer>—— 据 Chacon and Straub, Pro Git, 2nd ed., 2014 整理</footer></div><p><a href="/cs/swe-testing-strategy">上一课</a>把「改对了没有」交给三层判据，但判据必须挂在某次具体改动上：这一笔到底改了什么、哪一笔引入的回归。早先的<a href="/cs/vcs-changeset">版本控制与变更</a>课把变更集定义为可命名的快照差，并说明测试要与实现同提交，历史才能回放规格。本课写 git 把这套模型落在什么数据结构上：blob、tree、commit 与引用。后面的分支、构建与交付各课默认你已经会这个内部模型，不再把「分支是指针」当新知讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>备份目录式的历史三条都做不到：命名靠手工（v2-final-final2），无完整性校验（盘坏了不知道少了哪个字节），分支靠整树复制（几 GB 一份）。工程需要的账本是：任何历史状态可命名，任何字节被改可察觉，从任何状态派生新线近乎免费。而且这三条要在仓库增长后仍然成立——按仓库大小收费的分支，会让人不敢分支。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><span class="marginnote">暂存区（index）可以想象成给下一个 commit 打包的购物车：<code>git add</code> 是把改好的商品放进去，<code>git commit</code> 是结账拍照。没放进购物车的改动，永远进不了这张快照——「我改了为什么提交里没有」多半是忘了 add。</span></p><p>git 只有四种对象。blob 存文件内容；tree 存目录，即「名字到 blob 或子 tree」的映射；commit 指向一个 tree，记录父提交、作者与提交消息；tag 给任意对象贴注解。所有对象以内容的 SHA-1 哈希为名，放进 .git/objects。工作区任何时刻对应某个 commit；暂存区（index）是下一个 commit 的 tree 的草稿，<code>git add</code> 把文件内容做成 blob 放进去，<code>git commit</code> 把草稿冻结成 tree 并新建 commit 对象。分支与标签都是引用（ref）：存着 40 位十六进制哈希的指针文件；HEAD 记录当前所在。</p>',8)),(t(),l(A,null,{default:e(()=>[s(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C2%5B%22commit%EF%BC%9Atree%20%2B%20%E7%88%B6%20%2B%20%E6%B6%88%E6%81%AF%22%5D%20--%3E%20T%5B%22tree%EF%BC%9A%E7%9B%AE%E5%BD%95%E6%98%A0%E5%B0%84%22%5D%0A%20%20C2%20--%3E%20C1%5B%22%E7%88%B6%20commit%22%5D%0A%20%20T%20--%3E%20B1%5B%22blob%EF%BC%9Aa.c%22%5D%0A%20%20T%20--%3E%20B2%5B%22blob%EF%BC%9Autil.c%22%5D%0A%20%20BR%5B%22%E5%88%86%E6%94%AF%20main%EF%BC%9A40%20%E4%BD%8D%E5%93%88%E5%B8%8C%22%5D%20--%3E%20C2%0A%20%20HEAD%5B%22HEAD%22%5D%20--%3E%20BR%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[E("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"内容寻址长出三个推论。其一，去重：内容相同即哈希相同，未变动的文件在提交之间共享同一个 blob。其二，完整性：哈希即校验和，历史任何字节被改，其后所有对象的哈希链全断，篡改必然留痕。其三，分支近乎免费：建分支只是写一个指针文件，删除只是删文件，与仓库大小无关。commit 存的是快照不是差异，diff 是按需计算的派生视图；delta 压缩是打包（packfile）时的存储优化，不改变模型。",-1)),(t(),l(A,null,{default:e(()=>[s(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E6%8F%90%E4%BA%A4%20100%20%E4%B8%AA%E7%89%88%E6%9C%AC%E9%83%BD%E6%B2%A1%E6%94%B9%E7%9A%84%20README%22%5D%20--%3E%20Q1%5B%22%E5%AF%B9%E8%B1%A1%E5%BA%93%E6%9F%A5%20hash%3Dab12%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%93%88%E5%B8%8C%E5%B7%B2%E5%AD%98%E5%9C%A8%22%7C%20R%5B%22%E5%A4%8D%E7%94%A8%E5%90%8C%E4%B8%80%20blob%EF%BC%8C%E4%B8%8D%E9%87%8D%E5%A4%8D%E5%AD%98%E5%82%A8%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%93%88%E5%B8%8C%E4%B8%8D%E5%AD%98%E5%9C%A8%22%7C%20N%5B%22%E5%86%99%E5%85%A5%E6%96%B0%20blob%22%5D%0A%20%20F2%5B%22%E6%9C%89%E4%BA%BA%E6%94%B9%E4%BA%86%20blob%20%E9%87%8C%E7%9A%84%E4%B8%80%E4%B8%AA%E5%AD%97%E8%8A%82%22%5D%20--%3E%20H2%5B%22%E5%86%85%E5%AE%B9%E5%8F%98%EF%BC%8Chash%20%E5%8F%98%E6%88%90%20cdef%22%5D%0A%20%20H2%20--%3E%20BR%5B%22%E5%BC%95%E7%94%A8%E5%AE%83%E7%9A%84%20tree%20%E5%93%88%E5%B8%8C%E9%9A%8F%E4%B9%8B%E6%94%B9%E5%8F%98%22%5D%0A%20%20BR%20--%3E%20CC%5B%22%E7%88%B6%E9%93%BE%E4%B8%8A%E6%89%80%E6%9C%89%20commit%20%E5%93%88%E5%B8%8C%E6%96%AD%E8%A3%82%22%5D%0A%20%20CC%20--%3E%20D%5B%22%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%AF%A1%E6%94%B9%E6%97%A0%E5%A4%84%E8%97%8F%E8%BA%AB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">40 个十六进制字符对应 160 位的 SHA-1。暴力伪造指定内容约需 2 的 160 次方次尝试；即便已实现的结构性碰撞也要约 2 的 63 次方次计算，远超个人能力。所以日常把哈希当文件名、当校验和，工程上是够用的。</span></p><p><span class="marginnote">backup 目录式的 v2-final-final2 是把「内容」和「名字」两个职责压在同一个文件名上的症状。git 的拆法：哈希管内容身份，引用（main、v1.2）管人类可读的名字，两边各自演化互不干扰。</span></p><p><span class="marginnote">.git/refs/heads/feature 是一个文本文件，内容 40 个十六进制字符加一个换行。「分支很贵所以不敢开」的旧习惯——每次分支复制整棵工作树——在这里失去物质基础，这也是下一课短命分支策略可行的前提。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SHA-1 的构造性碰撞在密码学上已被做出，git 社区在向 SHA-256 迁移；日常遇到的完整性问题多半不是「被碰撞了」，而是对象库被外力改过或磁盘坏了。git 只做文本三方合并，管不了语义：两笔各自编译通过、合在一起坏的改动，只有上一课的集成层抓得住。二进制文件的冲突不可文本合并。.git 目录是对象库不是备份，异地冗余要另做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>git 是内容寻址的对象库：blob、tree、commit、tag，哈希即身份即校验。</li><li>暂存区是下一个 tree 的草稿；提交是快照，diff 是派生视图。</li><li>分支是 41 字节的指针文件，创建与删除与仓库大小无关。</li><li>完整性由哈希链保证，改历史必留痕；SHA-256 迁移在推进。</li><li>语义冲突归测试层，git 只裁决文本三角。</li><li>出处：Chacon and Straub, <em>Pro Git</em>, 2nd ed., Apress, 2014。</li></ul>',7))])}const u=n(c,[["render",m]]);export{h as __pageData,u as default};
